args.sql:
ALTER TABLE environmentalreadingscore
ADD COLUMN read_year INTEGER;

UPDATE environmentalreadingscore
SET read_year = EXTRACT(YEAR FROM readtimestamp);

CREATE TABLE EnvironmentalReadingsCore_Partitioned (
    envreadregistry BIGINT NOT NULL,
    monitorcode CHARACTER NOT NULL,
    readtimestamp TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    showcaseref CHARACTER NULL,
    tempc SMALLINT NULL,
    tempvar24h REAL NULL,
    relhumidity INTEGER NULL,
    humvar24h SMALLINT NULL,
    airpresshpa REAL NULL,
    read_year INTEGER,
    PRIMARY KEY (envreadregistry)
) PARTITION BY RANGE (read_year);

CREATE TABLE EnvironmentalReadingsCore_2023 PARTITION OF EnvironmentalReadingsCore_Partitioned
FOR VALUES FROM (2023) TO (2024);

CREATE TABLE EnvironmentalReadingsCore_2024 PARTITION OF EnvironmentalReadingsCore_Partitioned
FOR VALUES FROM (2024) TO (2025);

